head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일(wframe_SKT-321_(WSQ-956)_main.xml)실행 후 그리드컬럼을 마우스로 더블클릭한다.
    //1. Run the sample file (wframe_SKT-321_ (WSQ-956) _main.xml) and double-click the grid column with the mouse.
    //Verify step 1. The selectbox is displayed and the values you can select are displayed (previously no value is shown). 
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wfm_main_gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_wfm_main_gridView1___selectbox_col1_itemTable').css('display') == 'block'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
